const qs = [
  ['name finiteInAffine','"$HORIZON_BIN" search --name "FiniteInAffine" -n 100 --json'],
  ['name finiteInAffine wildcard','"$HORIZON_BIN" search --name "*finiteInAffine*" -n 100 --json'],
  ['name Orbits','"$HORIZON_BIN" search --name "*OrbitsInAffineOpen*" -n 100 --json'],
  ['type projective finite','"$HORIZON_BIN" search --type "?π.IsProjective → Scheme.FiniteInAffine ?X" -n 30 --json'],
  ['type hquasi finite','"$HORIZON_BIN" search --type "?π.IsHQuasiProjective → Scheme.FiniteInAffine ?X" -n 30 --json']
];
for (const [name,cmd] of qs) {
  const r=await tools.exec_command({cmd,workdir:'/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild',yield_time_ms:30000,max_output_tokens:30000});
  text(`### ${name}\n${r.output}`);
}

const cwd="/home/axel/LeanAlgebraicGeometry-Horizon";
const cmds=[
  `rg --files -g 'README*' -g '*roadmap*' | sed -n '1,120p'`,
  `wc -l README.md MainProjects/Algebraic-Jacobian-Challenge-Rebuild/README.md 2>/dev/null`,
  `sed -n '1,220p' MainProjects/Algebraic-Jacobian-Challenge-Rebuild/README.md`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({
  cmd,
  workdir:cwd,
  yield_time_ms:10000,
  max_output_tokens:30000
})));
rs.forEach((r,i)=>text(`--- docs ${i+1} ---\n${r.output}`));

const r = await tools.exec_command({
  cmd: "\"$HORIZON_BIN\" task show \"$ARCHON_HORIZON_TASK\" --json",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
  yield_time_ms: 30000,
  max_output_tokens: 30000
});
text(`exit=${r.exit_code}\n${r.output}`);

const r = await tools.exec_command({
  cmd: "\"$HORIZON_BIN\" roadmap list --json | jq '[.items[]|select((.id|contains(\"build-reach\")) or (.title|ascii_downcase|contains(\"reachab\")))|{id,title,status,parent}]'",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
  yield_time_ms: 10000,
  max_output_tokens: 10000
});
text(r.output);

const cmds=[
 ["finite","\"$HORIZON_BIN\" search --name finiteInAffine -n 100 --json 2>/dev/null | jq -r '.[] | select(.library==\"Algebraic-Jacobian-Challenge\" or .library==\"Algebraic-Jacobian-Challenge-Rebuild\") | [.library,.kind,.name,.signature,.file,(.line|tostring)] | @tsv'"],
 ["orbits","\"$HORIZON_BIN\" search --name OrbitsInAffineOpen -n 100 --json 2>/dev/null | jq -r '.[] | select(.library==\"Algebraic-Jacobian-Challenge\" or .library==\"Algebraic-Jacobian-Challenge-Rebuild\") | [.library,.kind,.name,.signature,.file,(.line|tostring)] | @tsv'"],
 ["hquasi","\"$HORIZON_BIN\" search --name isHQuasiProjective -n 100 --json 2>/dev/null | jq -r '.[] | select(.library==\"Algebraic-Jacobian-Challenge\" or .library==\"Algebraic-Jacobian-Challenge-Rebuild\") | [.library,.kind,.name,.signature,.file,(.line|tostring)] | @tsv'"],
 ["projectivity","\"$HORIZON_BIN\" search \"projectivity curve\" -n 100 --json 2>/dev/null | jq -r '.[] | select(.library==\"Algebraic-Jacobian-Challenge\" or .library==\"Algebraic-Jacobian-Challenge-Rebuild\") | [.library,.kind,.name,.signature,.file,(.line|tostring)] | @tsv'"]
];
const out=await Promise.all(cmds.map(async ([n,cmd])=>{
 const r=await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:30000,max_output_tokens:30000});
 return `### ${n}\n${r.output}`;
}));
out.forEach(text);

const cmds = [
  ["files", "rg --files AlgebraicJacobian | rg 'FiniteStage|FiniteInAffine|StableAffine|Orbit|Pic0'"],
  ["imports", "rg -n --glob '*.lean' 'FiniteStage|OrbitsInAffineOpen|FiniteInAffine|Galois|orbit|Orbit' AlgebraicJacobian/Picard AlgebraicJacobian/Descent | head -n 500"],
  ["recent", "git log --oneline --decorate -n 25 -- AlgebraicJacobian/Picard AlgebraicJacobian/Descent"],
  ["rootimports", "rg -n 'Pic0FiniteStage|FiniteInAffine|StableAffine|OrbitAffine' AlgebraicJacobian.lean AlgebraicJacobian 2>/dev/null | head -n 400"]
];
const rs = await Promise.all(cmds.map(async ([name, cmd]) => {
  const r = await tools.exec_command({
    cmd,
    workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  });
  return {name, output:r.output, code:r.exit_code};
}));
for (const r of rs) text(`===== ${r.name} (exit ${r.code}) =====\n${r.output}`);

const base="/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/inbox/local/items";
const cwd="/home/axel/LeanAlgebraicGeometry-Horizon";
const kinds=["protection","conversation","memory","issue","hint","info"];
const countPromises=kinds.map(kind=>tools.exec_command({
  cmd:`rg -l '^kind: ${kind}$' ${base} | xargs rg -l '^status: open$' | wc -l`,
  workdir:cwd,
  yield_time_ms:10000,
  max_output_tokens:10000
}));
const otherPromises=[
  tools.exec_command({
    cmd:`"$HORIZON_BIN" inbox list --status open --json | jq '{warnings,visible_counts:(.items|group_by(.kind)|map({kind:.[0].kind,count:length})),attention}'`,
    workdir:cwd,yield_time_ms:10000,max_output_tokens:20000
  }),
  tools.exec_command({
    cmd:`"$HORIZON_BIN" task list --json | jq '{warnings,by_status:(.tasks|group_by(.status)|map({status:.[0].status,count:length})),running:[.tasks[]|select(.status=="running")|.id]}'`,
    workdir:cwd,yield_time_ms:10000,max_output_tokens:20000
  }),
  tools.exec_command({
    cmd:`"$HORIZON_BIN" roadmap list --focus AJCR.review-plan.p7-galois-descent --json | jq '{warnings,items:[.items[]|{id,status,owner,subtree_done,subtree_total}]}'`,
    workdir:cwd,yield_time_ms:10000,max_output_tokens:20000
  })
];
const rs=await Promise.all([...countPromises,...otherPromises]);
kinds.forEach((kind,i)=>text(`after_global_${kind}=${rs[i].output.trim()}`));
text(`--- after visible inbox ---\n${rs[6].output}`);
text(`--- after tasks ---\n${rs[7].output}`);
text(`--- after roadmap ---\n${rs[8].output}`);

