  const r = await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:20000});
  return {name, output:r.output};
}));
for (const r of rs) text(`===== ${r.name} =====\n${r.output}`);
